// HYPOTHETICAL CODE THAT JAVA FORBIDS:
// class HybridPrinter extends Printer, 3DPrinter {
//     // If we call hybrid.printDocument(), the compiler cannot know
//     // whether to print standard ink or 3D plastic!
// }

// JAVA'S REAL-WORLD SOLUTION: Composition or Interfaces
class RealHybridDevice {
    private Printer inkPrinter = new Printer();
    private 3DPrinter plasticPrinter = new 3DPrinter();

    public void printPaper() {
        inkPrinter.printDocument(); // Completely unambiguous
    }

    public void printPrototype() {
        plasticPrinter.printDocument(); // Completely unambiguous
    }
}

public class DiamondDemo {
    public static void main(String[] args) {
        RealHybridDevice dev = new RealHybridDevice();
        dev.printPaper();
        dev.printPrototype();
    }
}

