practiceProblems.solutionCode:
class Display {
    public void renderPicture(String content) {
        System.out.println("Displaying: " + content);
    }
}

class AudioSpeaker {
    public void emitSound(int volume) {
        System.out.println("Sound playing at volume: " + volume);
    }
}

class SmartTv {
    private Display display;
    private AudioSpeaker speaker;

    public SmartTv() {
        this.display = new Display();
        this.speaker = new AudioSpeaker();
    }

    public void streamShow(String showName, int volume) {
        display.renderPicture(showName);
        speaker.emitSound(volume);
    }
}

public class Main {
    public static void main(String[] args) {
        SmartTv tv = new SmartTv();
        tv.streamShow("Stranger Things", 15);
    }
}

class FileLogger {
    public void logToFile(String msg) {
        System.out.println("FILE LOG: " + msg);
    }
}

class NetworkLogger {
    public void sendOverNetwork(String msg) {
        System.out.println("NETWORK LOG: Sent packet to SIEM -> " + msg);
    }
}

class EnterpriseAuditLogger {
    private final FileLogger fileLogger = new FileLogger();
    private final NetworkLogger networkLogger = new NetworkLogger();

    public void dispatchAudit(String event) {
        fileLogger.logToFile(event);
        networkLogger.sendOverNetwork(event);
    }
}

public class Main {
    public static void main(String[] args) {
        EnterpriseAuditLogger auditor = new EnterpriseAuditLogger();
        auditor.dispatchAudit("[AUDIT-CRITICAL] User admin logged in");
    }
}

class LaserPrinter {
    public void printPage(String doc) {
        System.out.println("Laser printing 600dpi copy of: " + doc);
    }
}

class FlatbedScanner {
    public void scanPage(String doc) {
        System.out.println("Scanning paper document: " + doc);
    }
}

class AllInOneHub {
    private final LaserPrinter printer = new LaserPrinter();
    private final FlatbedScanner scanner = new FlatbedScanner();

    public void copyDocument(String doc) {
        scanner.scanPage(doc);
        printer.printPage(doc);
    }
}

public class Main {
    public static void main(String[] args) {
        AllInOneHub hub = new AllInOneHub();
        hub.copyDocument("Annual_Report.pdf");
    }
}

