class Car {
    public void drive(int mph) {
        System.out.println("Driving on road at " + mph + " mph");
    }
}

class FlightModule {
    public void fly(int altitudeFt) {
        System.out.println("Flying in air at " + altitudeFt + " ft");
    }
}

class FlyingCar extends Car {
    private FlightModule flightModule = new FlightModule();

    public void takeFlight(int altitude) {
        flightModule.fly(altitude);
    }
}

public class Main {
    public static void main(String[] args) {
        FlyingCar fc = new FlyingCar();
        fc.drive(65);
        fc.takeFlight(5000);
    }
}

class GpsNavigator {
    public String getCoordinates() { return "37.7749 N, 122.4194 W"; }
}

class BatteryMonitor {
    public int getChargeLevel() { return 84; }
}

class CombustionEngine {
    public int getFuelLevel() { return 45; }
}

class SmartVehicle {
    private final GpsNavigator gps = new GpsNavigator();
    private final BatteryMonitor battery = new BatteryMonitor();
    private final CombustionEngine engine = new CombustionEngine();

    public void printDashboardTelemetry() {
        System.out.println("=== HYBRID SMART TELEMETRY ===");
        System.out.println("Location: " + gps.getCoordinates());
        System.out.println("Battery State: " + battery.getChargeLevel() + "% Charge");
        System.out.println("Fuel State: " + engine.getFuelLevel() + "L Fuel Remaining");
    }
}

public class Main {
    public static void main(String[] args) {
        SmartVehicle vehicle = new SmartVehicle();
        vehicle.printDashboardTelemetry();
    }
}
